<script setup>import {onMounted,ref} from 'vue';import PageHero from '../components/PageHero.vue';import PersonCard from '../components/PersonCard.vue';import {images} from '../data/imageAssets';import {getPeople} from '../api/people';const people=ref([]),loading=ref(true),failed=ref(false);onMounted(async()=>{try{people.value=(await getPeople({page:1,pageSize:30})).list}catch{failed.value=true}finally{loading.value=false}})</script>
<template><PageHero title="历史人物" description="已公开人物资料" :image="images.historyPaper"/><section class="section"><div class="shell"><div v-if="loading" class="empty-state">正在加载人物资料…</div><div v-else-if="failed" class="empty-state">人物资料暂时无法加载，请稍后重试。</div><div v-else class="person-grid"><PersonCard v-for="person in people" :key="person.id" :person="person"/></div></div></section></template>
